T=/dd/SYS/termcapecho "@@CASE@@md5-agrees-with-the-host"/dd/CMDS/md5 $Techo "@@CASE@@btoa-atob-round-trip"/dd/CMDS/btoa < $T > /dd/tmp/t.btoa/dd/CMDS/atob < /dd/tmp/t.btoa > /dd/tmp/t.back/dd/CMDS/md5 /dd/tmp/t.backecho "@@CASE@@btoa-really-encodes"/dd/CMDS/md5 /dd/tmp/t.btoaecho "@@CASE@@uuencode-uudecode-round-trip"/dd/CMDS/cp $T /dd/tmp/enc.src/dd/CMDS/uuencode /dd/tmp/enc.src > /dd/tmp/t.uu/dd/CMDS/uudecode /dd/tmp/t.uu/dd/CMDS/md5 /dd/tmp/enc.srcecho "@@CASE@@uuencode-really-encodes"/dd/CMDS/wc -c /dd/tmp/t.uuecho "@@CASE@@todos-must-change-the-file"/dd/CMDS/cp $T /dd/tmp/w.txt/dd/CMDS/todos /dd/tmp/w.txt/dd/CMDS/md5 /dd/tmp/w.txtecho "@@CASE@@todos-toos9-round-trip-passes-trivially"/dd/CMDS/cp $T /dd/tmp/x.txt/dd/CMDS/todos /dd/tmp/x.txt/dd/CMDS/toos9 /dd/tmp/x.txt/dd/CMDS/md5 /dd/tmp/x.txtecho "@@CASE@@binhex-produces-hqx"/dd/CMDS/binhex $T > /dd/tmp/t.hqx/dd/CMDS/wc -c /dd/tmp/t.hqxecho "@@CASE@@checksums-agree-with-each-other"/dd/CMDS/sum $T/dd/CMDS/checksum $T/dd/CMDS/chksum $Techo "@@CASE@@cvtbase-converts"/dd/CMDS/cvtbase 255 16echo "@@CASE@@end"